以下是 **MQTT 实时数据流对接** 的完整工程实现。这段代码将把你之前设计的 3D 空间可视化组件与真实的传感器网络无缝连接，并内置了 IoT 场景必需的**断线重连、数据路由、安全认证**等特性。

---

# 🔌 MQTT 数据流对接实现

## 1. 自定义 Hook：`useGreenhouseMQTT`

封装 MQTT 生命周期、消息路由与状态管理，提供干净的 React 接口。

```jsx
// hooks/useGreenhouseMQTT.js
import { useEffect, useRef, useState } from 'react';
import mqtt from 'mqtt';

export function useGreenhouseMQTT(config) {
  const { brokerUrl, topics, username, password, tls = false } = config;

  const clientRef = useRef(null);
  const [sensorData, setSensorData] = useState({});
  const [devices, setDevices] = useState([]);
  const [connStatus, setConnStatus] = useState('connecting'); // connecting | connected | offline | error

  useEffect(() => {
    // 1. 初始化客户端
    const clientOpts = {
      clientId: `meerkat-agro-${Math.random().toString(16).slice(2, 8)}`,
      clean: true,
      reconnectPeriod: 5000, // 自动重连间隔
      connectTimeout: 10000,
    };

    if (tls) {
      clientOpts.protocol = 'wss'; // WebSocket Secure (推荐边缘端使用)
      clientOpts.ca = config.caCert; // 可选：自定义 CA 证书
    } else {
      clientOpts.protocol = 'ws';
    }

    if (username) clientOpts.username = username;
    if (password) clientOpts.password = password;

    const client = mqtt.connect(brokerUrl, clientOpts);
    clientRef.current = client;

    // 2. 事件监听
    client.on('connect', () => {
      setConnStatus('connected');
      console.log('[MQTT] ✅ 已连接至边缘网关');
      // 订阅所有配置的主题
      topics.forEach(topic => client.subscribe(topic, { qos: 1 }));
    });

    client.on('message', (topic, payload) => {
      try {
        const data = JSON.parse(payload.toString());

        // 路由分发：根据 Topic 前缀解析数据结构
        if (topic.startsWith('greenhouse/v1/telemetry/env/')) {
          const zoneId = topic.split('/').pop();
          setSensorData(prev => ({ ...prev, [zoneId]: data }));
        } 
        else if (topic.startsWith('greenhouse/v1/telemetry/device/')) {
          const deviceId = topic.split('/').pop();
          setDevices(prev => {
            const idx = prev.findIndex(d => d.id === deviceId);
            const newItem = { id: deviceId, ...data };
            return idx >= 0 ? prev.map((d, i) => i === idx ? newItem : d) : [...prev, newItem];
          });
        }
      } catch (err) {
        console.warn(`[MQTT] 解析失败 topic=${topic}:`, err.message);
      }
    });

    client.on('offline', () => setConnStatus('offline'));
    client.on('error', (err) => {
      console.error('[MQTT] ❌ 连接异常:', err);
      setConnStatus('error');
    });

    // 3. 清理函数
    return () => {
      client.end(false, () => {
        clientRef.current = null;
        setConnStatus('disconnected');
      });
    };
  }, [brokerUrl, topics, username, password, tls]);

  return { sensorData, devices, connStatus };
}
```

---

## 2. 集成到 Spatial Dashboard

将 Hook 接入之前的 3D 场景，替换掉 Mock 数据，并增加连接状态指示器。

