// components/SpatialDashboard.jsx
import React from 'react';
import { Canvas } from '@react-three/fiber';
import { GreenhouseScene } from './GreenhouseScene'; // 上一步的 3D 场景
import { useGreenhouseMQTT } from '../hooks/useGreenhouseMQTT';
import { OrbitControls } from '@react-three/drei';

export default function SpatialDashboard() {
  // 配置 MQTT 连接（实际部署时从环境变量读取）
  const { sensorData, devices, connStatus } = useGreenhouseMQTT({
    brokerUrl: 'ws://192.168.1.100:9001', // 边缘网关 WebSocket 端口
    topics: [
      'greenhouse/v1/telemetry/env/+',
      'greenhouse/v1/telemetry/device/+'
    ],
    username: 'agro_admin',
    password: process.env.REACT_APP_MQTT_PASS,
    tls: true
  });

  const statusBadge = {
    connecting: { text: '⏳ 初始化...', color: 'text-amber-400' },
    connected: { text: '🟢 实时同步中', color: 'text-emerald-400' },
    offline: { text: '🔴 网络断开', color: 'text-rose-400' },
    error: { text: '⚠️ 连接异常', color: 'text-orange-400' }
  }[connStatus];

  return (
    <div className="w-full h-screen bg-[#121418] relative overflow-hidden">
      {/* 3D 渲染层 */}
      <Canvas shadows camera={{ position: [15, 10, 15], fov: 50 }}>
        <GreenhouseScene sensorData={sensorData} devices={devices} />
        <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 2.5} />
      </Canvas>

      {/* 状态指示器 (左上角) */}
      <div className="absolute top-4 left-4 z-10">
        <div className="bg-slate-900/90 backdrop-blur px-4 py-2 rounded-lg border border-slate-700 shadow-lg">
          <div className="flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${connStatus === 'connected' ? 'bg-emerald-400 animate-pulse' : 'bg-slate-500'}`} />
            <span className={`text-sm font-mono ${statusBadge.color}`}>{statusBadge.text}</span>
          </div>
        </div>
      </div>

      {/* 图例 (左下角) */}
      <div className="absolute bottom-4 left-4 z-10 bg-slate-900/80 p-3 rounded-lg border border-slate-700 text-white text-xs">
        <h3 className="font-bold mb-1">🌡️ VPD 热力图例</h3>
        <div className="flex gap-3">
          <span className="flex items-center gap-1"><span className="w-3 h-3 bg-blue-500 rounded"></span> 湿润 (&lt;0.8)</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 bg-green-400 rounded"></span> 适宜 (0.8~1.2)</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 bg-red-500 rounded"></span> 干燥 (&gt;1.2)</span>
        </div>
      </div>
    </div>
  );
}
```

---

## 3. 🛡️ 生产环境关键实践（必读）

| 风险点 | 解决方案 |
|:---|:---|
| **高频数据刷屏** | MQTT 若发布频率 >10Hz，React 重绘会卡顿。建议在 Hook 中加入 `lodash.throttle` 或改用 `requestAnimationFrame` 同步状态。 |
| **边缘断网容错** | 系统需支持 **Local-First**：断网时 3D 场景保留最后一次已知状态，并显示“离线缓存模式”水印。 |
| **安全认证** | 生产环境必须启用 `TLS/SSL`。使用 `wss://` 协议，并在 MQTT Broker 侧配置 ACL 限制 Topic 读写权限。 |
| **数据时钟同步** | 传感器时间可能与边缘网关不同步。建议在 Payload 中携带 `timestamp: Date.now()`，前端统一按网关时间轴渲染。 |
| **内存泄漏防护** | `useEffect` 的 cleanup 已处理 `client.end()`。若组件频繁卸载/挂载，建议将 MQTT 客户端提升至 `App` 层或 `Redux Toolkit` 管理。 |

---

## 4. 调试与验证清单

1. **本地代理测试**：使用 `docker run -p 1883:1883 -p 9001:9001 emqx/emqx:latest` 快速搭建测试 Broker。
2. **Payload 模拟**：用 `mosquitto_pub` 发送测试数据：
   ```bash
   mosquitto_pub -h localhost -t "greenhouse/v1/telemetry/env/0-0" \
     -m '{"temp": 26.5, "hum": 68, "vpd": 0.95, "lux": 12000}'
   ```
3. **Chrome DevTools**：打开 Network → WS 标签，确认消息收发延迟 <50ms。

